+#[test]
+fn a_child_on_the_parents_endpoint_gets_the_key_the_parent_used() {
+    let env = Env::new(
+        "delegate-key-fallback",
+        json!({ "steps": [delegate("hi"), { "text": "hello" }, { "text": "done" }] }),
+    );
+    env.config(&agent_config(&env, ""));
+    let out =
+        env.run_with(&[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "or-key-AAAA")], &["run", "--no-learn", "go"]);
+    assert!(out.status.success(), "{}", text(&out));
+    // Parent, child, parent: the parent's resolved OpenRouter key reaches the
+    // child under the name it reads.
+    assert_eq!(
+        auth_seen(&env),
+        vec![json!("Bearer or-k…"), json!("Bearer or-k…"), json!("Bearer or-k…")],
+        "{}",
+        text(&out)
+    );
+}
+
+#[test]
+fn with_no_key_the_run_fails_before_a_request() {
+    let env =
+        Env::new("delegate-no-key", json!({ "steps": [delegate("hi"), { "text": "hello" }, { "text": "done" }] }));
+    env.config(&agent_config(&env, ""));
+    let out = env.run_with(&[("OPENAI_API_KEY", ""), ("OPENROUTER_API_KEY", "")], &["run", "--no-learn", "go"]);
+    assert!(!out.status.success(), "{}", text(&out));
+    assert!(text(&out).contains("no API key: set OPENAI_API_KEY or OPENROUTER_API_KEY"), "{}", text(&out));
+    assert!(env.requests().is_empty(), "{}", text(&out));
+}
