+/// OpenRouter's usual name. An empty secret name is a keyless endpoint: no
+/// lookup and no fallback.
+pub fn api_key_with_name(secret_name: &str) -> Option<(String, String)> {
+    if secret_name.is_empty() {
+        return None;
+    }
+    if let Some(v) = get(secret_name) {
+        return Some((secret_name.to_string(), v));
+    }
+    get("OPENROUTER_API_KEY").map(|v| ("OPENROUTER_API_KEY".to_string(), v))
+}
